      OPTIONS        CLOB,                                    -- Key=Value lines reported by the terminal
      ATT_STAMP      VARCHAR2(30)   DEFAULT '0' NOT NULL,
      OP_STAMP       VARCHAR2(30)   DEFAULT '0' NOT NULL,
      PHOTO_STAMP    VARCHAR2(30)   DEFAULT '0' NOT NULL,
