  ddl('HDR_COMMANDS', q'[
    CREATE TABLE HDR_COMMANDS (
      CMD_ID       NUMBER         NOT NULL,                  -- the C:<id>: of the protocol
      SN           VARCHAR2(50)   NOT NULL,
