      CONTENT_KEY  VARCHAR2(40)   NOT NULL,                  -- length + hash, for de-duplication
      TITLE        NVARCHAR2(120),
      STATUS       VARCHAR2(10)   DEFAULT 'pending' NOT NULL,  -- pending / sent / done / failed
      ATTEMPTS     NUMBER(3)      DEFAULT 0 NOT NULL,
      RETURN_CODE  VARCHAR2(20),
