      SENT_AT      DATE,
      RETURNED_AT  DATE,
      CONSTRAINT HDR_COMMANDS_PK PRIMARY KEY (CMD_ID))]');
  ddl('HDR_COMMANDS_SN_IX', 'CREATE INDEX HDR_COMMANDS_SN_IX ON HDR_COMMANDS (SN, STATUS, CMD_ID)');
  ddl('HDR_COMMANDS_KEY_IX', 'CREATE INDEX HDR_COMMANDS_KEY_IX ON HDR_COMMANDS (SN, CONTENT_KEY)');
  -- the checks of the last minutes or the last day (heartbeat, punch, clock, arrows that turn): a range of the
  -- terminal's newest commands, not the month of history it keeps
  ddl('HDR_COMMANDS_AT_IX', 'CREATE INDEX HDR_COMMANDS_AT_IX ON HDR_COMMANDS (SN, CREATED_AT)');
  ddl('HDR_COMMANDS_SENT_IX', 'CREATE INDEX HDR_COMMANDS_SENT_IX ON HDR_COMMANDS (SN, SENT_AT)');

