      DECISION   VARCHAR2(10),                             -- NULL: waiting; accepted / rejected
      DECIDED_BY VARCHAR2(255),
      DECIDED_AT DATE,
      CONSTRAINT HDR_HELD_PK PRIMARY KEY (HELD_ID))]');
  ddl('HDR_HELD_W_IX', 'CREATE INDEX HDR_HELD_W_IX ON HDR_HELD (DECISION, SN)');

  ddl('HDR_REJECTS', q'[
    CREATE TABLE HDR_REJECTS (
      LOG_ID  NUMBER        NOT NULL,
      LOGGED_AT DATE        DEFAULT SYSDATE NOT NULL,
