      CYCLE      NUMBER(3)      DEFAULT 1 NOT NULL,
      CONSTRAINT HDR_SHIFTS_PK PRIMARY KEY (SHIFT_ID),
      CONSTRAINT HDR_SHIFTS_UK UNIQUE (ALIAS))]');

  -- week cycles: DAY_INDEX 0 = Monday .. 6 = Sunday (+7 per further week); month: 0..30 (+31 per month)
  ddl('HDR_SHIFT_DAYS', q'[
    CREATE TABLE HDR_SHIFT_DAYS (
      SHIFT_ID  NUMBER    NOT NULL,
      DAY_INDEX NUMBER(4) NOT NULL,
      TT_ID     NUMBER    NOT NULL,
      CONSTRAINT HDR_SHIFT_DAYS_PK PRIMARY KEY (SHIFT_ID, DAY_INDEX, TT_ID))]');

  ddl('HDR_SCHEDULES', q'[
    CREATE TABLE HDR_SCHEDULES (
