  -- each employee's department schedules (the engine reads them per employee)
  ddl('HDR_DEPT_SCHEDULES_IX', 'CREATE INDEX HDR_DEPT_SCHEDULES_IX ON HDR_DEPT_SCHEDULES (DEPT_CODE, START_DATE, END_DATE)');

  -- one-day override: TT_ID empty = day off
  ddl('HDR_TEMP_SCHEDULES', q'[
    CREATE TABLE HDR_TEMP_SCHEDULES (
