  ddl('HDR_MANUAL_PUNCHES_IX', 'CREATE INDEX HDR_MANUAL_PUNCHES_IX ON HDR_MANUAL_PUNCHES (EMP_CODE, PUNCH_TIME)');
  ddl('HDR_MANUAL_PUNCHES_ST_IX', 'CREATE INDEX HDR_MANUAL_PUNCHES_ST_IX ON HDR_MANUAL_PUNCHES (STATUS, CREATED_AT)');

  ddl('HDR_OVERTIME', q'[
    CREATE TABLE HDR_OVERTIME (
      OT_ID      NUMBER         NOT NULL,
      EMP_CODE   VARCHAR2(30)   NOT NULL,
      START_TIME DATE           NOT NULL,
      END_TIME   DATE           NOT NULL,
