-- ---------------------------------------------------------------- hdr_policy.pks
CREATE OR REPLACE PACKAGE HDR_POLICY AS
  -- Dated versions of the timetables, the shifts (their cycle and their days) and the attendance rules: an edit of
  -- the working hours never changes the days before it. The program's rules (hader/policy_history.py), the same
  -- versions (HDR_TIMETABLE_VERSIONS, HDR_SHIFT_VERSIONS, HDR_RULE_VERSIONS), read by HDR_ENGINE:
  -- * the first edit keeps what applied before as the baseline, from the beginning of time;
  -- * an ordinary save (a form of APEX app 141, the settings) applies from today; the first one keeps the baseline
  --   only once a day before today has something calculated (a punch, a manual punch, a schedule of any kind).
  --   Saves of one day make one version;
  -- * a dated edit starts on its first day and stays open until the next edit starts, or ends on its last day:
  --   from the day after, what it set comes back to what applied just before it (but what an open edit made
  --   inside the period set stays). A period inside which another edit starts is refused;
  -- * each edit keeps what it set itself and every version is rebuilt from the edits (replay), so an edit dated
  --   between others never undoes a later one.
  -- Scopes: 'timetable' (target TT_ID), 'shift' (SHIFT_ID), 'rules' (target 0).
  -- Values travel as "KEY=value" lines (CHR(10)): the columns of HDR_TIMETABLES (CHECK_IN 'HH24:MI', MUST_IN 'Y'/'N',
  -- ...), a shift's CYCLE_UNIT, CYCLE and DAYS ('day:tt,day:tt', day 0 = Monday of week 1), the att.* settings as
  -- HDR_SETTINGS holds them. Refusals are ORA-206xx with an Arabic - English message for the page.

  OPEN_END  CONSTANT DATE := DATE '2199-12-31';     -- a schedule without a last day stays open until another one
  BEGINNING CONSTANT DATE := DATE '0001-01-01';     -- a baseline's first day

  -- a dated edit from p_from to p_to (both days counted; NULL: open). Returns the edit's VER_ID.
  FUNCTION save_edit (p_scope IN VARCHAR2, p_target IN NUMBER, p_from IN DATE, p_to IN DATE, p_reason IN NVARCHAR2,
                      p_values IN NVARCHAR2, p_actor IN VARCHAR2 DEFAULT NULL) RETURN NUMBER;
  -- what applies on a day, and the row itself (HDR_TIMETABLES ...), as "KEY=value" lines
  FUNCTION values_at (p_scope IN VARCHAR2, p_target IN NUMBER, p_day IN DATE) RETURN NVARCHAR2;
  FUNCTION live_values (p_scope IN VARCHAR2, p_target IN NUMBER) RETURN NVARCHAR2;
  -- one value of such lines
  FUNCTION value_of (p_lines IN NVARCHAR2, p_key IN VARCHAR2) RETURN NVARCHAR2;

  -- an ordinary save of a timetable or a shift (APEX forms): p_before = live_values taken just before it.
  -- What it changed applies from today; the days before keep what they had.
  PROCEDURE saved (p_scope IN VARCHAR2, p_target IN NUMBER, p_before IN NVARCHAR2, p_actor IN VARCHAR2 DEFAULT NULL);
  -- an ordinary save of one rule (HDR_UI.set_value), just before it is set
  PROCEDURE rule_saving (p_key IN VARCHAR2, p_value IN VARCHAR2, p_actor IN VARCHAR2 DEFAULT NULL);
  -- versions written by the Hader server (hader/native_write.py): the stored results are worked out again from
  -- p_from (not before the first day with a stored result)
  PROCEDURE recalculate (p_from IN DATE);

  -- schedules: no last day (NULL) is open (OPEN_END). A new one trims what the employee / department had in its
  -- days (the one before ends the day before it starts). A started one keeps its shift and first day: only its last
  -- day moves, from yesterday on. Returns the schedule's id.
  FUNCTION schedule_save (p_id IN NUMBER, p_emp_code IN VARCHAR2, p_shift IN NUMBER, p_start IN DATE, p_end IN DATE)
    RETURN NUMBER;
  FUNCTION dept_schedule_save (p_id IN NUMBER, p_dept IN VARCHAR2, p_shift IN NUMBER, p_start IN DATE, p_end IN DATE)
    RETURN NUMBER;
  -- 'emp' / 'dept': a started schedule ends yesterday (returns that day, so the days calculated keep it); one not
  -- started yet goes (NULL); one wholly in the past goes only with p_past = 'Y' (correcting a mistake)
  FUNCTION schedule_end (p_kind IN VARCHAR2, p_id IN NUMBER, p_past IN VARCHAR2 DEFAULT 'N') RETURN DATE;

  -- removing: a shift in schedules, or a timetable used by a shift, an earlier version of one or a one-day schedule,
  -- is refused (the days calculated with it would change); otherwise it goes with its versions
  FUNCTION timetable_use (p_id IN NUMBER) RETURN NVARCHAR2;   -- where it is used; NULL: nowhere
  PROCEDURE timetable_delete (p_id IN NUMBER);
  PROCEDURE shift_delete (p_id IN NUMBER);

