-- ---------------------------------------------------------------- hdr_demo.pks
CREATE OR REPLACE PACKAGE HDR_DEMO AS
  -- A sample company for trying the plug-ins before any terminal is connected: 2 areas, 4 departments,
  -- 36 employees, 5 terminals (one waiting for approval), the punches of the last weeks, leave and a holiday.
  -- While it is loaded the background job keeps it alive: today's punches arrive at their times.
  -- Everything it adds is marked (codes 9001.., DEMO..) and removed by clear. It refuses to mix with real data.
  PROCEDURE load (p_days IN NUMBER DEFAULT 35);
  PROCEDURE clear;
  PROCEDURE tick;   -- called by HDR_JOBS.tick while the sample is loaded
  PROCEDURE english_names;   -- the sample's employees named as this release names them, in Arabic and English
END HDR_DEMO;
/

